#!/bin/bash
set -euo pipefail
cd /testbed
printf '%s' '' | base64 -d > /tmp/equivalent.patch
printf '%s' '' | base64 -d > /tmp/equivalent-test.patch
patch -p1 < /tmp/equivalent.patch
if [[ -s /tmp/equivalent-test.patch ]]; then patch -p1 < /tmp/equivalent-test.patch; fi

mkdir -p /app/output_data
printf '%s\n' '{"status":"alternative_checkpoint"}' > /app/output_data/provisional_checkpoint.json
printf '%s\n' '{"source_task_id":"scikit-learn__scikit-learn-12973","preserved":true}' > /app/output_data/preserved_source_facts.json
python /app/task_file/scripts/event_worker.py --workspace /testbed
python /app/task_file/scripts/write_manifest.py
